import random


class Snake:
    EAT_FOOD_SCORE_INCREMENT = 100
    INITIAL_LENGTH = 1
    MAX_POSITIONS_FOR_COLLISION_CHECK = 2

    def __init__(self, SCREEN_WIDTH, SCREEN_HEIGHT, BLOCK_SIZE, food_position):
        self.length = self.INITIAL_LENGTH
        self._SCREEN_WIDTH = SCREEN_WIDTH
        self._SCREEN_HEIGHT = SCREEN_HEIGHT
        self._BLOCK_SIZE = BLOCK_SIZE
        self.positions = [((self._SCREEN_WIDTH / 2), (self._SCREEN_HEIGHT / 2))]
        self.score = 0
        self-food_position = food_position

    @property
    def SCREEN_WIDTH(self):
        return self._SCREEN_WIDTH

    @property
    def SCREEN_HEIGHT(self):
        return self._SCREEN_HEIGHT

    @property
    def BLOCK_SIZE(self):
        return self._BLOCK_SIZE

    @property
    def food_position(self):
        return self._food_position

    @food_position.setter
    def food_position(self, value):
        self._food_position = value

    def move(self, direction):
        cur = self.positions[0]
        x, y = direction

        new = self._calculate_new_position(cur, x, y)

        if new == self.food_position:
            self.eat_food()

        if self._should_reset(new):
            self.reset()
        else:
            self._update_positions(new)

    def _calculate_new_position(self, cur, x, y):
        return (
            ((cur[0] + (x * self.BLOCK_SIZE)) % self.SCREEN_WIDTH),
            (cur[1] + (y * self.BLOCK_SIZE)) % self.SCREEN_HEIGHT,
        )

    def _should_reset(self, new):
        return len(self.positions) > self.MAX_POSITIONS_FOR_COLLISION_CHECK and new in self.positions[2:]

    def _update_positions(self, new):
        self.positions.insert(0, new)
        if len(self.positions) > self.length:
            self.positions.pop()

    def random_food_position(self):
        while self._food_position in self.positions:
            self._food_position = self._generate_random_food_position()

    def _generate_random_food_position(self):
        return (
            random.randint(0, self.SCREEN_WIDTH // self.BLOCK_SIZE - 1) * self.BLOCK_SIZE,
            random.randint(0, self.SCREEN_HEIGHT // self.BLOCK_SIZE - 1) * self.BLOCK_SIZE
        )

    def reset(self):
        self.length = self.INITIAL_LENGTH
        self.positions = [((self.SCREEN_WIDTH / 2), (self.SCREEN_HEIGHT / 2))]
        self.score = 0
        self.random_food_position()

    def eat_food(self):
        self.length += 1
        self.score += self.EAT_FOOD_SCORE_INCREMENT
        self.random_food_position()
